const rejectCausalEdge = `-- name: RejectCausalEdge :one
DELETE FROM causal_edge
WHERE id = $1::uuid AND status = 'suggested'
RETURNING id, workspace_id, from_node_id, to_node_id, type, weight, confidence, metadata, provenance, created_at, created_by, proposed_by, status
`

func (q *Queries) RejectCausalEdge(ctx context.Context, edgeID pgtype.UUID) (CausalEdge, error) {
	row := q.db.QueryRow(ctx, rejectCausalEdge, edgeID)
	var i CausalEdge
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.FromNodeID,
		&i.ToNodeID,
		&i.Type,
		&i.Weight,
		&i.Confidence,
		&i.Metadata,
		&i.Provenance,
		&i.CreatedAt,
		&i.CreatedBy,
		&i.ProposedBy,
		&i.Status,
	)
	return i, err
}

const touchCausalNode = `-- name: TouchCausalNode :exec
UPDATE causal_node SET last_observed_at = now()
WHERE id = $1::uuid
`

func (q *Queries) TouchCausalNode(ctx context.Context, nodeID pgtype.UUID) error {
	_, err := q.db.Exec(ctx, touchCausalNode, nodeID)
	return err
}
